import{_ as t,o as e,c as i,a2 as s}from"./chunks/framework.CqGPl1zp.js";const d="/newx-doc/assets/%E6%99%BA%E8%B0%B1-%E5%AE%98%E6%96%B9.Y003PEpz.png",g=JSON.parse('{"title":"【模型接入】智谱 GLM","description":"","frontmatter":{},"headers":[],"relativePath":"ai/glm.md","filePath":"ai/glm.md","lastUpdated":null}'),r={name:"ai/glm.md"};function h(n,a,l,p,o,c){return e(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="【模型接入】智谱-glm" tabindex="-1">【模型接入】智谱 GLM <a class="header-anchor" href="#【模型接入】智谱-glm" aria-label="Permalink to &quot;【模型接入】智谱 GLM&quot;">​</a></h1><p>项目基于 Spring AI + 自己实现的 <code>models/zhipu</code>，实现 <a href="https://zhipuai.cn/" target="_blank" rel="noreferrer">智谱 GLM</a> 的接入，底层复用兼容 OpenAI 协议的客户端：</p><table tabindex="0"><thead><tr><th>功能</th><th>模型</th><th>Spring AI 客户端</th></tr></thead><tbody><tr><td>AI 对话</td><td>GLM-5.2、GLM-5.1、GLM-5.0 等</td><td>ZhiPuChatModel</td></tr><tr><td>AI 绘画</td><td><a href="https://github.com/THUDM/CogView" target="_blank" rel="noreferrer">CogView</a></td><td>暂未接入</td></tr></tbody></table><h2 id="_1-申请密钥" tabindex="-1">1. 申请密钥 <a class="header-anchor" href="#_1-申请密钥" aria-label="Permalink to &quot;1. 申请密钥&quot;">​</a></h2><p>智谱 AI 有开源模型，可以私有化部署。</p><p>不过它最新、最强的模型通常没有开源，所以只能通过官方的 API 服务接入。</p><h3 id="_1-1-申请智谱-ai-密钥" tabindex="-1">1.1 申请智谱 AI 密钥 <a class="header-anchor" href="#_1-1-申请智谱-ai-密钥" aria-label="Permalink to &quot;1.1 申请智谱 AI 密钥&quot;">​</a></h3><p>① 在 <a href="https://www.bigmodel.cn/invite?icode=ANYhs5i3q9fak%2Be3nUWbhGczbXFgPRGIalpycrEwJ28%3D" target="_blank" rel="noreferrer">智谱 AI 开放平台</a> 上，注册一个账号。目前，默认注册就送 2500w tokens，还是蛮爽的。</p><p>② 在 <a href="https://open.bigmodel.cn/usercenter/apikeys" target="_blank" rel="noreferrer">API keys</a> 菜单，复制系统默认 API key 即可。</p><hr><p>申请完成后，可以在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单，进行密钥的配置。只需要填写“密钥”，不需要填写“自定义 API URL”（因为 Spring AI 默认官方地址）。如下图所示：</p><p><img src="'+d+`" alt="官方的密钥配置"></p><h2 id="_2-模型配置" tabindex="-1">2. 模型配置 <a class="header-anchor" href="#_2-模型配置" aria-label="Permalink to &quot;2. 模型配置&quot;">​</a></h2><p>友情提示：</p><p>目前 <code>ai_model</code> 表中，已经预置了一些模型，可以直接使用！！！</p><h3 id="_2-1-ai-对话" tabindex="-1">2.1 AI 对话 <a class="header-anchor" href="#_2-1-ai-对话" aria-label="Permalink to &quot;2.1 AI 对话&quot;">​</a></h3><p>使用 <a href="./chat">《AI 对话》</a> 时，需要在 [AI 大模型 -&gt; 控制台 -&gt; 模型配置] 菜单，配置对应的聊天模型，并选择前面配置的智谱 API 密钥。</p><p>不同模型的 <code>max_tokens</code>（回复数 Token 数）上限不同，可以参考下表填写：</p><table tabindex="0"><thead><tr><th>模型标识</th><th><code>max_tokens</code> 最大输出 Tokens</th></tr></thead><tbody><tr><td><code>glm-5.2</code></td><td>131072</td></tr><tr><td><code>glm-5.1</code></td><td>131072</td></tr><tr><td><code>glm-5</code></td><td>131072</td></tr><tr><td><code>glm-5-turbo</code></td><td>131072</td></tr></tbody></table><h3 id="_2-2-ai-绘画" tabindex="-1">2.2 AI 绘画 <a class="header-anchor" href="#_2-2-ai-绘画" aria-label="Permalink to &quot;2.2 AI 绘画&quot;">​</a></h3><p>暂未接入。</p><h2 id="_3-如何使用" tabindex="-1">3. 如何使用？ <a class="header-anchor" href="#_3-如何使用" aria-label="Permalink to &quot;3. 如何使用？&quot;">​</a></h2><p>① 如果你的项目里需要直接通过 <code>@Resource</code> 注入 ZhiPuChatModel 等对象，需要把 <code>application.yaml</code> 配置文件里的 <code>yudao.ai.zhipu</code> 配置项，替换成你的！</p><div class="language-YAML vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">yudao</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    zhipu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 智谱 AI（GLM）</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      enable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      api-key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${ZHIPU_API_KEY}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">glm-5.2</span></span></code></pre></div><p>② 如果你希望使用 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单的密钥配置，则可以通过 AiModelService 的 <code>#getChatModel(...)</code> 方法，获取对应的模型对象。</p><hr><p>① 和 ② 这两者的后续使用，就是标准的 Spring AI 客户端的使用，调用对应的方法即可。</p><p>另外，ZhiPuAiChatModelTests 里有对应的测试用例，可以参考。</p>`,28)])])}const A=t(r,[["render",h]]);export{g as __pageData,A as default};
